WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_m_reverse'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '相遇反求', 'kp-trv-m-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "相遇反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "已知相遇结果，倒推某人的速度或出发时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“两人相遇后，甲再走2小时到达B地，乙再走4.5小时到达A地”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式（相遇后交叉走模型）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是一个极高频的固化模型。相遇后，甲走的是原来乙走过的路，乙走的是甲走过的路。根据 S=VT 可以推导出神级公式："}]}, {"type": "katexBlock", "attrs": {"content": "\\frac{V_甲}{V_乙} = \\sqrt{\\frac{t_乙}{t_甲}}"}}, {"type": "paragraph", "content": [{"type": "text", "text": "（注：t甲 和 t乙 指的是相遇后他们各自走到对面终点所花的时间）"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别出'相遇后继续走到对面'的模型] --> B[提取相遇后甲的时间 t甲 和 乙的时间 t乙]\nB --> C[套用开方公式: V甲/V乙 = √(t乙/t甲)]\nC --> D[得出两人的精确速度比例]\nD --> E[结合题干其他条件(如全长或某人真实速度)求解]"}}]}$$ AS jsonb), NULL, '相遇反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "相遇反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_m_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
